app.delete("/api/links", requireAuth, async (c2) => {
  const { slugs } = await c2.req.json();
  const user = c2.get("user");
  if (!slugs || slugs.length === 0)
    return c2.json({ error: "Slugs required" }, 400);
  const placeholders = slugs.map(() => "?").join(",");
  const { results: targetLinks } = await c2.env.DB.prepare(`SELECT r2_key FROM links WHERE user_id = ? AND slug IN (${placeholders})`).bind(user.id, ...slugs).all();
  const keysToDelete = targetLinks.filter((l2) => l2.r2_key).map((l2) => ({ Key: l2.r2_key }));
  if (keysToDelete.length > 0) {
    const s3Client = getS3Client(c2.env);
    await s3Client.send(new DeleteObjectsCommand({
      Bucket: c2.env.R2_BUCKET_NAME,
      Delete: { Objects: keysToDelete }
    })).catch((e2) => console.error("R2 deletion failed", e2));
  }
  await c2.env.DB.prepare(`DELETE FROM links WHERE user_id = ? AND slug IN (${placeholders})`).bind(user.id, ...slugs).run();
  return c2.json({ message: "Deleted successfully" });
});
app.post("/api/feedback", async (c2) => {
  const { email, message, context } = await c2.req.json();
  if (!message)
    return c2.json({ error: "Message required" }, 400);
  const fullMessage = context ? `[Context: ${context}] ${message}` : message;
  await c2.env.DB.prepare("INSERT INTO feedback (email, message) VALUES (?, ?)").bind(email || "", fullMessage).run();
  return c2.json({ message: "Feedback received" });
});
app.get("/api/feedback", requireAuth, async (c2) => {
  const { results: feedback } = await c2.env.DB.prepare("SELECT * FROM feedback ORDER BY created_at DESC LIMIT 100").all();
  return c2.json({ data: feedback });
});
app.post("/api/tools/usage", async (c2) => {
  const { toolId } = await c2.req.json();
  if (!toolId)
    return c2.json({ error: "toolId required" }, 400);
  const ip = c2.req.header("cf-connecting-ip") || "Unknown";
  const country = c2.req.header("cf-ipcountry") || "Unknown";
  await c2.env.DB.prepare("INSERT INTO tool_usage (tool_id, ip, country) VALUES (?, ?, ?)").bind(toolId, ip, country).run();
  return c2.json({ message: "Usage recorded" });
});
app.get("/api/tools/trending", async (c2) => {
  const { results } = await c2.env.DB.prepare(`
    SELECT tool_id, COUNT(*) as usageCount 
    FROM tool_usage 
    WHERE timestamp >= date('now', '-7 days')
    GROUP BY tool_id 
    ORDER BY usageCount DESC
  `).all();
  return c2.json({ data: results });
});
